import { Suspense } from "react";
import { prisma } from "@/lib/prisma";
import BeritaClient from "./BeritaClient";
import BeritaHeader from "./BeritaHeader";

/**
 * SKELETON BERITA (Identik dengan grid BeritaClient)
 */
function BeritaSkeleton() {
  return (
    <div className="flex-1 overflow-y-auto pb-20 pr-2 animate-pulse">
      {/* Toolbar Skeleton */}
      <div className="flex flex-col md:flex-row justify-between items-center gap-4 mb-8">
        <div className="h-11 w-full flex-1 bg-white dark:bg-[#0f172a] border border-slate-200 dark:border-white/10 rounded-xl" />
        <div className="h-11 w-full md:w-32 bg-white dark:bg-[#0f172a] border border-slate-200 dark:border-white/10 rounded-xl" />
      </div>

      {/* Grid Skeleton */}
      <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-6">
        {[1, 2, 3, 4, 5, 6, 7, 8].map((i) => (
          <div key={i} className="bg-white dark:bg-[#1e293b] rounded-2xl border border-slate-100 dark:border-white/5 overflow-hidden shadow-sm h-[380px] relative">
            <div className="absolute inset-0 -translate-x-full animate-[shimmer_2s_infinite] bg-gradient-to-r from-transparent via-white/10 to-transparent" />
            <div className="aspect-[4/3] bg-slate-200 dark:bg-slate-800" />
            <div className="p-4 space-y-4">
              <div className="h-5 w-full bg-slate-200 dark:bg-slate-800 rounded" />
              <div className="h-5 w-2/3 bg-slate-200 dark:bg-slate-800 rounded" />
              <div className="flex gap-3">
                <div className="h-3 w-16 bg-slate-100 dark:bg-slate-800/50 rounded" />
                <div className="h-3 w-16 bg-slate-100 dark:bg-slate-800/50 rounded" />
              </div>
              <div className="space-y-2 pt-2">
                <div className="h-2.5 w-full bg-slate-50 dark:bg-slate-800/30 rounded" />
                <div className="h-2.5 w-full bg-slate-50 dark:bg-slate-800/30 rounded" />
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

/**
 * SERVER COMPONENT (Pengambil Data)
 */
async function BeritaData() {
  const posts = await prisma.berita.findMany({
    orderBy: { createdAt: "desc" },
  });

  return <BeritaClient initialPosts={posts} />;
}

export default function BeritaPage() {
  return (
    <div className="relative h-[calc(100vh-140px)] flex flex-col font-sans">
      {/* HEADER STATIS */}
      <BeritaHeader />

      {/* KONTEN DINAMIS */}
      <Suspense fallback={<BeritaSkeleton />}>
        <BeritaData />
      </Suspense>
    </div>
  );
}
